const fs = require('fs');

// ---------------------------------------------------------
// STEP 2: RAW TRACE EVENT MODEL
// ---------------------------------------------------------
class RawTraceEvent {
  constructor(rawJson) {
    this.threadId = rawJson.thread_id !== undefined ? rawJson.thread_id : null;
    this.queryId = rawJson.query_id !== undefined ? rawJson.query_id : null;
    this.seq = rawJson.seq !== undefined ? rawJson.seq : 0;
    this.elapsedUs = rawJson.elapsed_us !== undefined ? rawJson.elapsed_us : 0;
    this.eventType = rawJson.event_type || 'UNKNOWN';
    this.stage = rawJson.stage || '';
    this.details = rawJson.details || {};
  }

  get activityScope() {
    if (this.details && this.details.query && String(this.details.query).includes('/* TABLE_SNAPSHOT */')) {
      return 'MYSQL_INTERNAL';
    }
    return this.details.activity_scope || (this.details.table_kind === 'INTERNAL_TEMPORARY' ? 'INTERNAL_TEMPORARY' : 'USER_DATA');
  }

  get isUserData() {
    return this.activityScope === 'USER_DATA';
  }

  get isMysqlInternal() {
    return this.activityScope === 'MYSQL_INTERNAL';
  }

  get isInternalTemporary() {
    return this.activityScope === 'INTERNAL_TEMPORARY';
  }
}

// ---------------------------------------------------------
// STEP 3: JSONL TRACE READER
// ---------------------------------------------------------
class TraceReader {
  static parseContent(content) {
    if (!content || typeof content !== 'string') return [];
    const lines = content.split('\n');
    const events = [];

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;

      try {
        const json = JSON.parse(line);
        if (json && typeof json === 'object') {
          events.push(new RawTraceEvent(json));
        }
      } catch (err) {
        try {
          // Retry parsing by sanitizing unescaped Windows backslashes in file paths
          const sanitizedLine = line.replace(/\\([^\/\\"'nrtbfu])/g, '/$1').replace(/\\/g, '/');
          const json = JSON.parse(sanitizedLine);
          if (json && typeof json === 'object') {
            events.push(new RawTraceEvent(json));
          }
        } catch (e2) {}
      }
    }

    return events;
  }

  static readFromFile(filePath) {
    try {
      if (!fs.existsSync(filePath)) return [];
      const content = fs.readFileSync(filePath, 'utf8');
      return TraceReader.parseContent(content);
    } catch (err) {
      console.error(`[TraceReader Error] Failed to read ${filePath}:`, err.message);
      return [];
    }
  }
}

// ---------------------------------------------------------
// STEP 4-8: QUERY RECONSTRUCTION
// ---------------------------------------------------------
class RowChange {
  constructor(type, table, schema, rowKey, details) {
    this.type = type; // 'INSERT', 'UPDATE', 'DELETE'
    this.table = table || '';
    this.schema = schema || '';
    this.rowKey = rowKey || null;
    this.insertedValues = details.insertedValues || null;
    this.beforeValues = details.beforeValues || null;
    this.afterValues = details.afterValues || null;
    this.deletedValues = details.deletedValues || null;
  }
}

class QueryTrace {
  constructor(threadId, queryId) {
    this.threadId = threadId;
    this.queryId = queryId;
    this.sql = '';
    this.commandType = 'UNKNOWN';
    this.startTimeUs = null;
    this.endTimeUs = null;
    this.durationUs = 0;
    this.tables = [];
    this.indexes = [];
    this.accessPaths = [];
    this.rowsExamined = 0;
    this.rowsAffected = null;
    this.events = [];
    this.userEvents = [];
    this.internalEvents = [];
    this.rowChanges = [];
    this.resultRows = [];
    this.executionInfo = {
      operators: [],
      accessPaths: [],
      indexes: []
    };
    this.hasError = false;
    this.errorDetails = null;
  }
}

class QueryReconstructor {
  static reconstructQueries(events) {
    if (!Array.isArray(events) || events.length === 0) return [];

    // Group events by (thread_id, query_id)
    const queryGroups = new Map();

    for (const ev of events) {
      if (ev.threadId === null || ev.queryId === null) continue;
      const key = `${ev.threadId}_${ev.queryId}`;
      if (!queryGroups.has(key)) {
        queryGroups.set(key, []);
      }
      queryGroups.get(key).push(ev);
    }

    const reconstructedQueries = [];

    for (const [key, groupEvents] of queryGroups.entries()) {
      // Sort strictly by sequence
      groupEvents.sort((a, b) => a.seq - b.seq);

      const firstEv = groupEvents[0];
      const queryTrace = new QueryTrace(firstEv.threadId, firstEv.queryId);
      queryTrace.events = groupEvents;

      const tablesSet = new Set();
      const indexesSet = new Set();
      const accessPathsSet = new Set();
      const operatorsMap = new Map();

      let updateBeforePending = [];
      let lastProjectedColumns = [];

      for (const ev of groupEvents) {
        // Categorize user vs internal events
        if (ev.isUserData) {
          queryTrace.userEvents.push(ev);
        } else if (ev.isMysqlInternal) {
          queryTrace.internalEvents.push(ev);
        }

        // Timing
        if (queryTrace.startTimeUs === null || ev.elapsedUs < queryTrace.startTimeUs) {
          queryTrace.startTimeUs = ev.elapsedUs;
        }
        if (queryTrace.endTimeUs === null || ev.elapsedUs > queryTrace.endTimeUs) {
          queryTrace.endTimeUs = ev.elapsedUs;
        }

        // SQL & Command Info
        if (ev.eventType === 'COMMAND_START' && ev.details.query) {
          queryTrace.sql = ev.details.query;
        }
        if (ev.eventType === 'AST_DISPATCH' && ev.details.cmd_type) {
          queryTrace.commandType = ev.details.cmd_type;
        }

        // Completion / Affected Rows / Errors
        if (ev.eventType === 'COMMAND_END') {
          if (ev.details.affected_rows !== undefined) {
            queryTrace.rowsAffected = ev.details.affected_rows;
          }
          if (ev.details.error !== undefined && ev.details.error !== 0) {
            queryTrace.hasError = true;
            queryTrace.errorDetails = ev.details;
          }
        }

        // Table & Index metadata
        if (ev.details.table) {
          if (ev.isUserData || !ev.details.activity_scope) {
            tablesSet.add(ev.details.table);
          }
        }
        if (ev.details.index_name) {
          indexesSet.add(ev.details.index_name);
        }
        if (ev.details.access_path) {
          accessPathsSet.add(ev.details.access_path);
        }

        // Operator lifecycle
        if (ev.eventType === 'OPERATOR_REGISTER' || ev.eventType === 'OPERATOR_OPEN' || ev.eventType === 'OPERATOR_CLOSE' || ev.eventType === 'TABLE_SCAN_START') {
          const opId = ev.details.operator_id;
          if (opId !== undefined) {
            let op = operatorsMap.get(opId);
            if (!op) {
              op = {
                operatorId: opId,
                parentOperatorId: ev.details.parent_operator_id || 0,
                iterator: ev.details.iterator || '',
                accessPath: ev.details.access_path || '',
                table: ev.details.table || '',
                index: ev.details.index_name || '',
                invocationId: ev.details.invocation_id || 1,
                rows: 0
              };
              operatorsMap.set(opId, op);
            }
            if (ev.details.iterator) op.iterator = ev.details.iterator;
            if (ev.details.access_path) op.accessPath = ev.details.access_path;
            if (ev.details.table) op.table = ev.details.table;
            if (ev.details.index_name) op.index = ev.details.index_name;
            if (ev.details.invocation_id) op.invocationId = ev.details.invocation_id;
            if (ev.details.operator_rows !== undefined) op.rows = ev.details.operator_rows;
          }
        }

        // Rows Examined
        if (ev.eventType === 'ROW_FETCH' && ev.isUserData) {
          queryTrace.rowsExamined++;
        } else if (ev.eventType === 'TABLE_SCAN_END' && ev.details.rows_examined !== undefined) {
          if (ev.details.rows_examined > queryTrace.rowsExamined) {
            queryTrace.rowsExamined = ev.details.rows_examined;
          }
        }

        // STEP 5: Row Change Reconstruction (User Data only)
        if (ev.isUserData) {
          if (ev.eventType === 'ROW_INSERTED') {
            queryTrace.rowChanges.push(new RowChange(
              'INSERT',
              ev.details.table || '',
              ev.details.schema || '',
              ev.details.row_key || null,
              { insertedValues: ev.details.inserted_values || null }
            ));
          } else if (ev.eventType === 'ROW_DELETED') {
            queryTrace.rowChanges.push(new RowChange(
              'DELETE',
              ev.details.table || '',
              ev.details.schema || '',
              ev.details.row_key || null,
              { deletedValues: ev.details.deleted_values || null }
            ));
          } else if (ev.eventType === 'ROW_UPDATE_BEFORE') {
            updateBeforePending.push(ev);
          } else if (ev.eventType === 'ROW_UPDATE_AFTER') {
            // Pair with matching ROW_UPDATE_BEFORE
            let beforeEv = null;
            if (updateBeforePending.length > 0) {
              // Match by table and row_key if available, else take last pending
              const matchIdx = updateBeforePending.findIndex(b => {
                const sameTable = (b.details.table === ev.details.table);
                const sameKey = JSON.stringify(b.details.row_key) === JSON.stringify(ev.details.row_key);
                return sameTable && sameKey;
              });
              if (matchIdx !== -1) {
                beforeEv = updateBeforePending.splice(matchIdx, 1)[0];
              } else {
                beforeEv = updateBeforePending.shift();
              }
            }

            queryTrace.rowChanges.push(new RowChange(
              'UPDATE',
              ev.details.table || '',
              ev.details.schema || '',
              ev.details.row_key || null,
              {
                beforeValues: beforeEv ? (beforeEv.details.before_values || null) : null,
                afterValues: ev.details.after_values || null
              }
            ));
          }
        }

        // Physical B+ Tree Page Visit
        if (ev.eventType === 'BTREE_PAGE_VISIT') {
          if (!queryTrace.executionInfo.physicalIndexAccess) {
            queryTrace.executionInfo.physicalIndexAccess = [];
          }
          queryTrace.executionInfo.physicalIndexAccess.push({
            spaceId: ev.details.space_id,
            pageNo: ev.details.page_no,
            level: ev.details.level,
            isLeaf: ev.details.is_leaf,
            indexName: ev.details.index_name || '',
            elapsedUs: ev.elapsedUs
          });
        }

        // Buffer Pool Page Access
        if (ev.eventType === 'BUFFER_POOL_HIT' || ev.eventType === 'BUFFER_POOL_MISS') {
          if (!queryTrace.executionInfo.pageAccesses) {
            queryTrace.executionInfo.pageAccesses = [];
          }
          queryTrace.executionInfo.pageAccesses.push({
            spaceId: ev.details.space_id,
            pageNo: ev.details.page_no,
            isHit: ev.eventType === 'BUFFER_POOL_HIT',
            elapsedUs: ev.elapsedUs
          });
        }

        // Lock Events
        if (ev.eventType === 'LOCK_GRANTED' || ev.eventType === 'LOCK_WAIT') {
          if (!queryTrace.executionInfo.lockEvents) {
            queryTrace.executionInfo.lockEvents = [];
          }
          queryTrace.executionInfo.lockEvents.push({
            lockType: ev.details.lock_type || 'RECORD',
            lockMode: ev.details.lock_mode || 'X',
            table: ev.details.table || '',
            pageNo: ev.details.page_no || 0,
            granted: ev.eventType === 'LOCK_GRANTED',
            waitingTrxId: ev.details.waiting_trx_id || 0,
            waitingThreadId: ev.details.waiting_thread_id || 0,
            blockingTrxId: ev.details.blocking_trx_id || 0,
            blockingThreadId: ev.details.blocking_thread_id || 0,
            elapsedUs: ev.elapsedUs
          });
        }

        // MVCC Read View & Version Events
        if (ev.eventType === 'MVCC_READ_VIEW' || ev.eventType === 'MVCC_VERSION_CHECK' || ev.eventType === 'MVCC_UNDO_FOLLOW' || ev.eventType === 'MVCC_VERSION_SELECTED') {
          if (!queryTrace.executionInfo.mvcc) {
            queryTrace.executionInfo.mvcc = {
              readViews: [],
              versionChecks: [],
              undoTraversal: [],
              selectedVersions: []
            };
          }
          if (ev.eventType === 'MVCC_READ_VIEW') {
            queryTrace.executionInfo.mvcc.readViews.push({
              creatorTrxId: ev.details.creator_trx_id,
              lowLimitId: ev.details.low_limit_id,
              upLimitId: ev.details.up_limit_id,
              elapsedUs: ev.elapsedUs
            });
          } else if (ev.eventType === 'MVCC_VERSION_CHECK') {
            queryTrace.executionInfo.mvcc.versionChecks.push({
              readerTrxId: ev.details.reader_trx_id,
              recordTrxId: ev.details.record_trx_id,
              visible: ev.details.visible,
              table: ev.details.table,
              elapsedUs: ev.elapsedUs
            });
          } else if (ev.eventType === 'MVCC_UNDO_FOLLOW') {
            queryTrace.executionInfo.mvcc.undoTraversal.push({
              fromTrxId: ev.details.from_trx_id,
              toTrxId: ev.details.to_trx_id,
              pageNo: ev.details.page_no,
              elapsedUs: ev.elapsedUs
            });
          } else if (ev.eventType === 'MVCC_VERSION_SELECTED') {
            queryTrace.executionInfo.mvcc.selectedVersions.push({
              readerTrxId: ev.details.reader_trx_id,
              recordTrxId: ev.details.record_trx_id,
              table: ev.details.table,
              elapsedUs: ev.elapsedUs
            });
          }
        }

        // Redo Log & WAL Events (Phase 23)
        if (ev.eventType === 'REDO_RECORD_GENERATED' || ev.eventType === 'REDO_LOG_WRITE' || ev.eventType === 'REDO_LOG_FLUSH') {
          if (!queryTrace.executionInfo.redo) {
            queryTrace.executionInfo.redo = {
              records: [],
              logWrites: [],
              flushes: []
            };
          }
          if (ev.eventType === 'REDO_RECORD_GENERATED') {
            queryTrace.executionInfo.redo.records.push({
              startLsn: ev.details.start_lsn,
              endLsn: ev.details.end_lsn,
              bytes: ev.details.bytes,
              elapsedUs: ev.elapsedUs
            });
          } else if (ev.eventType === 'REDO_LOG_WRITE') {
            queryTrace.executionInfo.redo.logWrites.push({
              writeLsn: ev.details.write_lsn,
              bytes: ev.details.bytes,
              elapsedUs: ev.elapsedUs
            });
          } else if (ev.eventType === 'REDO_LOG_FLUSH') {
            queryTrace.executionInfo.redo.flushes.push({
              flushLsn: ev.details.flush_lsn,
              elapsedUs: ev.elapsedUs
            });
          }
        }

        // Dirty Page Marking & Flushing Events (Phase 23)
        if (ev.eventType === 'DIRTY_PAGE_MARKED' || ev.eventType === 'DIRTY_PAGE_FLUSH') {
          if (!queryTrace.executionInfo.dirtyPages) {
            queryTrace.executionInfo.dirtyPages = {
              marked: [],
              flushed: []
            };
          }
          if (ev.eventType === 'DIRTY_PAGE_MARKED') {
            queryTrace.executionInfo.dirtyPages.marked.push({
              spaceId: ev.details.space_id,
              pageNo: ev.details.page_no,
              oldestLsn: ev.details.oldest_lsn,
              elapsedUs: ev.elapsedUs
            });
          } else if (ev.eventType === 'DIRTY_PAGE_FLUSH') {
            queryTrace.executionInfo.dirtyPages.flushed.push({
              spaceId: ev.details.space_id,
              pageNo: ev.details.page_no,
              newestLsn: ev.details.newest_lsn,
              elapsedUs: ev.elapsedUs
            });
          }
        }

        // STEP 6: Select Result Reconstruction
        if (ev.eventType === 'PROJECTION' && ev.details && ev.details.projected_columns) {
          lastProjectedColumns = ev.details.projected_columns;
        }
        if (ev.eventType === 'RESULT_SENT' || ev.eventType === 'PROJECTION') {
          if (ev.details && ev.details.values) {
            const cols = (ev.details.projected_columns && ev.details.projected_columns.length > 0)
              ? ev.details.projected_columns
              : (lastProjectedColumns && lastProjectedColumns.length > 0 ? lastProjectedColumns : Object.keys(ev.details.values || {}));
            queryTrace.resultRows.push({
              resultRowSeq: ev.details.result_row_seq || queryTrace.resultRows.length + 1,
              columns: cols,
              values: Array.isArray(ev.details.values) ? ev.details.values : Object.values(ev.details.values)
            });
          }
        }
      }

      // Calculate duration
      if (queryTrace.startTimeUs !== null && queryTrace.endTimeUs !== null) {
        queryTrace.durationUs = queryTrace.endTimeUs - queryTrace.startTimeUs;
      }

      if (!queryTrace.commandType || queryTrace.commandType === 'UNKNOWN') {
        const s = (queryTrace.sql || '').trim().toUpperCase();
        if (s.startsWith('SELECT')) queryTrace.commandType = 'SELECT';
        else if (s.startsWith('INSERT')) queryTrace.commandType = 'INSERT';
        else if (s.startsWith('UPDATE')) queryTrace.commandType = 'UPDATE';
        else if (s.startsWith('DELETE')) queryTrace.commandType = 'DELETE';
      }

      queryTrace.tables = Array.from(tablesSet);
      queryTrace.indexes = Array.from(indexesSet);
      queryTrace.accessPaths = Array.from(accessPathsSet);
      queryTrace.executionInfo.operators = Array.from(operatorsMap.values());
      queryTrace.executionInfo.accessPaths = queryTrace.accessPaths;
      queryTrace.executionInfo.indexes = queryTrace.indexes;

      // Reconstruct Operator Tree hierarchy
      const opNodes = Array.from(operatorsMap.values());
      const nodeMap = new Map();
      opNodes.forEach(op => {
        nodeMap.set(op.operatorId, { ...op, children: [] });
      });

      const rootNodes = [];
      nodeMap.forEach(node => {
        if (node.parentOperatorId && nodeMap.has(node.parentOperatorId)) {
          nodeMap.get(node.parentOperatorId).children.push(node);
        } else {
          rootNodes.push(node);
        }
      });
      queryTrace.executionInfo.operatorTree = rootNodes;

      reconstructedQueries.push(queryTrace);
    }

    return reconstructedQueries;
  }
}

// ---------------------------------------------------------
// STEP 9: TRANSACTION RECONSTRUCTION
// ---------------------------------------------------------
class TransactionTrace {
  constructor(threadId, beginQueryId) {
    this.threadId = threadId;
    this.beginQueryId = beginQueryId;
    this.endQueryId = null;
    this.statements = [];
    this.outcome = 'ACTIVE'; // 'COMMITTED', 'ROLLED_BACK', 'ACTIVE'
    this.startTimeUs = null;
    this.endTimeUs = null;
    this.durationUs = 0;
    this.totalRowChanges = 0;
  }
}

class TransactionReconstructor {
  static reconstructTransactions(reconstructedQueries) {
    if (!Array.isArray(reconstructedQueries) || reconstructedQueries.length === 0) return [];

    // Group reconstructed queries by threadId
    const threadQueries = new Map();
    for (const q of reconstructedQueries) {
      if (!threadQueries.has(q.threadId)) {
        threadQueries.set(q.threadId, []);
      }
      threadQueries.get(q.threadId).push(q);
    }

    const transactions = [];

    for (const [threadId, qList] of threadQueries.entries()) {
      // Sort queries by queryId / startTimeUs
      qList.sort((a, b) => a.queryId - b.queryId);

      let currentTx = null;

      for (const q of qList) {
        // Check for TRANSACTION_BEGIN event inside query
        const hasBegin = q.events.some(e => e.eventType === 'TRANSACTION_BEGIN');
        const hasCommit = q.events.some(e => e.eventType === 'TRANSACTION_COMMIT');
        const hasRollback = q.events.some(e => e.eventType === 'TRANSACTION_ROLLBACK');

        if (hasBegin) {
          if (currentTx && currentTx.outcome === 'ACTIVE') {
            // Implicit completion of previous active transaction
            currentTx.outcome = 'COMMITTED';
            transactions.push(currentTx);
          }
          currentTx = new TransactionTrace(threadId, q.queryId);
          currentTx.startTimeUs = q.startTimeUs;
        }

        if (currentTx) {
          currentTx.statements.push(q);
          currentTx.totalRowChanges += q.rowChanges.length;
          currentTx.endTimeUs = q.endTimeUs;

          if (hasCommit) {
            currentTx.endQueryId = q.queryId;
            currentTx.outcome = 'COMMITTED';
            if (currentTx.startTimeUs !== null && currentTx.endTimeUs !== null) {
              currentTx.durationUs = currentTx.endTimeUs - currentTx.startTimeUs;
            }
            transactions.push(currentTx);
            currentTx = null;
          } else if (hasRollback) {
            currentTx.endQueryId = q.queryId;
            currentTx.outcome = 'ROLLED_BACK';
            if (currentTx.startTimeUs !== null && currentTx.endTimeUs !== null) {
              currentTx.durationUs = currentTx.endTimeUs - currentTx.startTimeUs;
            }
            transactions.push(currentTx);
            currentTx = null;
          }
        }
      }

      if (currentTx) {
        if (currentTx.startTimeUs !== null && currentTx.endTimeUs !== null) {
          currentTx.durationUs = currentTx.endTimeUs - currentTx.startTimeUs;
        }
        transactions.push(currentTx);
      }
    }

    return transactions;
  }
}

class WaitForGraphReconstructor {
  static extractEdges(reconstructedQueries) {
    if (!Array.isArray(reconstructedQueries)) return [];
    const edges = [];
    for (const q of reconstructedQueries) {
      const lockEvents = q.executionInfo?.lockEvents || [];
      for (const lk of lockEvents) {
        const wId = lk.waitingTrxId || lk.waiting_trx_id;
        const bId = lk.blockingTrxId || lk.blocking_trx_id;
        if (!lk.granted && wId && bId) {
          edges.push({
            waiterTrxId: wId,
            blockerTrxId: bId,
            waiterThreadId: lk.waitingThreadId || lk.waiting_thread_id || q.threadId,
            blockerThreadId: lk.blockingThreadId || lk.blocking_thread_id || 0,
            lockMode: lk.lockMode || lk.lock_mode || 'X',
            table: lk.table || '',
            pageNo: lk.pageNo || lk.page_no || 0,
            queryId: q.queryId,
            elapsedUs: lk.elapsedUs || lk.elapsed_us
          });
        }
      }
    }
    return edges;
  }

  static detectCycles(edges) {
    if (!Array.isArray(edges) || edges.length === 0) return [];
    
    const adj = new Map();
    edges.forEach(e => {
      if (!adj.has(e.waiterTrxId)) adj.set(e.waiterTrxId, []);
      adj.get(e.waiterTrxId).push(e.blockerTrxId);
    });

    const cycles = [];
    const visited = new Set();
    const stack = new Set();

    function dfs(node, path) {
      visited.add(node);
      stack.add(node);
      path.push(node);

      const neighbors = adj.get(node) || [];
      for (const nxt of neighbors) {
        if (stack.has(nxt)) {
          const cyclePath = path.slice(path.indexOf(nxt));
          cyclePath.push(nxt);
          cycles.push(cyclePath);
        } else if (!visited.has(nxt)) {
          dfs(nxt, [...path]);
        }
      }

      stack.delete(node);
    }

    for (const node of adj.keys()) {
      if (!visited.has(node)) {
        dfs(node, []);
      }
    }

    return cycles;
  }
}

module.exports = {
  RawTraceEvent,
  TraceReader,
  RowChange,
  QueryTrace,
  QueryReconstructor,
  TransactionTrace,
  TransactionReconstructor,
  WaitForGraphReconstructor
};
